const text = $input.item.json.output[0].content[0].text;
const match = text.match(/\[[\s\S]*\]/);
if (!match) {
    throw new Error("JSON array not found.");
}
const parsed = JSON.parse(match[0]);
return parsed.map(item => ({
    json: {
        ...item,
        // Gmail HTML version
        mensagemEmail: item.mensagem
            .replace(/\\n/g, '\n')   // convert literal \n
            .replace(/\n/g, '<br>'), // convert actual newlines to HTML
        // Plain text version
        mensagemTexto: item.mensagem
            .replace(/\\n/g, '\n')
    }
}));
